# The arm is safely above the conveyor and the reference is leaving to the right.
# Wait in place while the next objects enter, then inspect their appearances.
obs = get_observation()
hold = {k: v for k, v in obs['state'].items() if k.endswith('joint_state')}
for i in range(100):
    obs, reward, terminated, truncated, info = step(hold)
    if terminated or truncated:
        break
print('waited', i + 1)
print('green', color_centroid(obs, 'cam_head', [0,130,40], [100,255,180], [0,110,640,240]))

